// =====================================================================
//  WORDS FROM THE AGORA GAME (Greekopolis)  -  more sections for the app
//
//  These sections use the same vocabulary as the Greekopolis game (data/vocab.json):
//  Bakery, School, Clothes & shops, Colours & describing, Pets, Town & transport,
//  Food & taverna, Park & weather, Home, Days & time.
//
//  They are plain data, edited like words.js. Word fields are the same as in words.js, plus:
//    badge   the emoji the monster holds up (a number badge for numbers, an emoji here)
//    plain   true for describing words (colours, sizes, directions ...) that have no little word
//    tpl     which third template sentence a noun gets: 'like' (Μου αρέσει …), 'here' (… είναι εδώ)
//            or 'mine' (the family style: Αυτός είναι ο φίλος μου)
//    sen     the English used inside template sentences when it differs from `en`
//    fem     (οι words) feminine plural, so the sentence starts Αυτές είναι …
//  Nouns get three template sentences automatically (see sentencesFor in words.js). A word listed in
//  TOWN_SENTENCES uses those hand-written sentences instead.
//
//  The Greek comes from the game's vocabulary list and has NOT been checked by a native speaker yet.
// =====================================================================

// ---- monster recipes: every word gets its own plush monster, holding up its emoji ----
const SHAPES = ['blob', 'cat', 'bunny', 'horn', 'tall', 'round'];
const FURS = ['fuzzy', 'plush', 'tie', 'split', 'fuzzy', 'plush'];
const BODY = ['#ff9f45', '#9c7bea', '#59c9a5', '#ef7c8e', '#5aa9f0', '#ffd166', '#9fd86b', '#e0aaff', '#ff8a6b', '#43b86a', '#f7a8d8', '#35b9c9'];
const BODY2 = ['#ffd23f', '#6d6875', '#a78bfa', '#f9a8d4', '#2f6fd8', '#ff6b6b', '#4f7cff', '#2fb36d'];
const EYES = ['#7ed321', '#f5d142', '#5fb7f0', '#e76f51', '#2fb36d', '#8dd0e8', '#f59a23', '#fbbf24'];
const MOUTHS = ['open', 'tongue', 'open'];
const TEETH = ['crooked', 'buck', 'fangs', 'gap'];
const ACCS = [['tuft'], ['bow'], ['glasses'], ['lashes'], ['earrings'], ['bow', 'lashes'], [], ['stache'], ['glasses', 'tuft']];
const mon = (i) => ({
  shape: SHAPES[(i * 5 + 1) % 6], fur: FURS[(i * 7 + 2) % 6],
  c: BODY[(i * 7) % 12], c2: BODY2[(i * 3) % 8], c3: BODY[(i * 5 + 4) % 12],
  ec: EYES[(i * 3 + 1) % 8], mouth: MOUTHS[(i * 5) % 3], teeth: TEETH[(i * 3) % 4],
  acc: ACCS[(i * 7 + 3) % 10], capC: BODY[(i * 5 + 8) % 12],
});
const holds = (i, badge) => ({ figs: [mon(i)], badge });
// a colour word: the monster IS that colour
const coloured = (i, hex) => ({ figs: [{ ...mon(i), c: hex, c2: hex, c3: hex, fur: 'plush' }] });

